data.minimal_example:
List<Language> _selectedLanguages = [];

FlutterTagging<Language>(
    initialItems: _selectedLanguages,
    textFieldConfiguration: TextFieldConfiguration(
        decoration: InputDecoration(
            labelText: 'Select Tags',
        ),
    ),
    findSuggestions: LanguageService.getLanguages,
    configureSuggestion: (lang) => SuggestionConfiguration(title: Text(lang.name)),
    configureChip: (lang) => ChipConfiguration(label: Text(lang.name)),
    onChanged: () {},
);
